WITH `t0` AS (SELECT `tenantId`, `entityId`, `version`, `market_stock_total` FROM `metric_group_ots_component_market_availability` FINAL WHERE `tenantId` = {p0:String}), `t1` AS (SELECT `a`.`market_stock_total` AS `stock` FROM (SELECT `entityId` FROM `entity_ots_component` WHERE `tenantId` = {p1:String} AND `state` = {p2:String}) AS `c` INNER ALL JOIN (SELECT `m`.`entityId` AS `entityId`, `m`.`market_stock_total` AS `market_stock_total` FROM `t0` AS `m` INNER ALL JOIN (SELECT `tenantId`, `entityId`, max(`version`) AS `version` FROM `t0` GROUP BY `tenantId`, `entityId`) AS `v` ON `m`.`tenantId` = `v`.`tenantId` AND `m`.`entityId` = `v`.`entityId` AND `m`.`version` = `v`.`version`) AS `a` ON `c`.`entityId` = `a`.`entityId`) SELECT `__typedhouse_input`.`stock` / (SELECT sum(`stock`) AS `stock` FROM `t1`) * {p3:Float64} AS `stock` FROM (SELECT `t1`.`stock` FROM `t1`) AS `__typedhouse_input`
